case $tz in
NORMAL) out=$(timeout 900 python3 bin/corp_action_daily_selfcheck.py 2>&1);;
UNSET) out=$(env -u TZ timeout 900 python3 bin/corp_action_daily_selfcheck.py 2>&1);;
NY) out=$(TZ=America/New_York timeout 900 python3 bin/corp_action_daily_selfcheck.py 2>&1);;
